<?php
declare(strict_types=1);
require __DIR__.'/../../private/form-utils.php';
require __DIR__.'/../../private/careers.php';
header('Cache-Control: no-store');
if (session_status() !== PHP_SESSION_ACTIVE) session_start();

$error=''; $notice='';
if (isset($_GET['logout'])) { $_SESSION=[]; session_destroy(); header('Location: ./',true,303); exit; }
if (!careers_admin_logged_in()) {
    if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['login_password'])) {
        if (careers_admin_login((string)$_POST['login_password'])) { header('Location: ./',true,303); exit; }
        // One message whether the password was wrong or the attempt limit is
        // reached. Saying which tells somebody probing the form that they found
        // a real account and only need to wait.
        $error = careers_login_blocked()
            ? 'Too many sign-in attempts. Please wait a few minutes and try again.'
            : 'Invalid password.';
    }
    $configured=careers_admin_hash()!=='';
    ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Careers Manager</title><style>body{margin:0;background:#06111d;color:#eef4f8;font-family:Inter,Segoe UI,Arial,sans-serif;display:grid;place-items:center;min-height:100vh}.box{width:min(430px,90vw);border:1px solid #29445c;background:#091a29;border-radius:16px;padding:28px}h1{margin:0 0 8px}.muted{color:#91a6b9;line-height:1.5}input{width:100%;box-sizing:border-box;background:#071522;border:1px solid #34546b;color:#fff;border-radius:8px;padding:12px;margin:12px 0}.btn{width:100%;border:0;border-radius:8px;padding:12px;background:#efb546;font-weight:850;cursor:pointer}.err{color:#ffd0d0}.warn{color:#f8d47c}</style></head><body><div class="box"><h1>Careers Manager</h1><p class="muted">Manage published jobs, careers-page content, projected-income scenarios, and applicants without editing code.</p><?php if(!$configured):?><p class="warn"><strong>Admin login is not configured yet.</strong><br>Set <code>CAREERS_ADMIN_PASSWORD_HASH</code> once during deployment. After login, the password can be changed from Settings.</p><?php else:?><form method="post"><label>Password</label><input type="password" name="login_password" required autofocus><button class="btn">Sign In</button></form><?php endif;?><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif;?></div></body></html><?php exit;
}

$config=careers_load_config(); $csrf=careers_csrf(); $tab=careers_clean((string)($_GET['tab']??'jobs'),30);
if ($tab==='export') { header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="careers-applications-'.gmdate('Ymd-His').'.csv"');echo careers_export_csv(careers_all_applications());exit; }
if (isset($_GET['resume'])) {
    // `careers_application_path()` now returns '' for anything that is not a
    // real APP-<date>-<hex> id, and `careers_resume_file()` refuses any path
    // that does not resolve inside the resumes directory. Both are needed: the
    // first stops `?resume=../../..` reaching the filesystem at all, the second
    // stops a stored path ever pointing outside it.
    $id=careers_clean((string)$_GET['resume'],80); $path=careers_application_path($id);
    if ($path!=='' && is_file($path)) {
        $app=json_decode((string)file_get_contents($path),true);
        $file=is_array($app)?careers_resume_file((string)($app['resume']['path']??'')):'';
        if ($file!=='') {
            // The applicant chose the original filename, so it is quoted and
            // stripped of anything that could break out of the header.
            $download=preg_replace('/[^A-Za-z0-9._ -]/','_',(string)($app['resume']['name']??basename($file)));
            if ($download==='') $download=basename($file);
            header('Content-Type: application/octet-stream');
            header('X-Content-Type-Options: nosniff');
            header('Content-Length: '.filesize($file));
            header('Content-Disposition: attachment; filename="'.$download.'"');
            readfile($file);exit;
        }
    }
    http_response_code(404);exit('Resume not found.');
}
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!careers_check_csrf((string)($_POST['csrf']??''))) { http_response_code(400); exit('Invalid session token.'); }
    $action=(string)($_POST['action']??'');
    if ($action==='save_site') {
        $config['site']['hero_kicker']=careers_clean((string)$_POST['hero_kicker'],100);
        $config['site']['hero_title']=careers_clean((string)$_POST['hero_title'],180);
        $config['site']['hero_copy']=careers_clean((string)$_POST['hero_copy'],1200);
        $config['site']['visual_title']=careers_clean((string)$_POST['visual_title'],180);
        $config['site']['visual_copy']=careers_clean((string)$_POST['visual_copy'],1200);
        $config['site']['visual_chips']=array_values(array_filter(array_map(fn($x)=>careers_clean((string)$x,80), preg_split('/\R/', (string)($_POST['visual_chips']??'')) ?: [])));
        $config['site']['roles_title']=careers_clean((string)$_POST['roles_title'],180);
        $config['site']['roles_copy']=careers_clean((string)$_POST['roles_copy'],1200);
        $config['site']['why_title']=careers_clean((string)$_POST['why_title'],180);
        $whyTitles=$_POST['why_item_title']??[]; $whyCopies=$_POST['why_item_copy']??[]; $why=[];
        for($i=0;$i<max(count($whyTitles),count($whyCopies));$i++){
            $t=careers_clean((string)($whyTitles[$i]??''),120); $c=careers_clean((string)($whyCopies[$i]??''),500);
            if($t!=='' || $c!=='') $why[]=['title'=>$t,'copy'=>$c];
        }
        $config['site']['why_items']=$why;
        $config['site']['apply_kicker']=careers_clean((string)$_POST['apply_kicker'],100);
        $config['site']['apply_title']=careers_clean((string)$_POST['apply_title'],180);
        $config['site']['apply_copy']=careers_clean((string)$_POST['apply_copy'],1200);
        $config['income']['enabled']=!empty($_POST['income_enabled']);
        $config['income']['title']=careers_clean((string)$_POST['income_title'],180);
        $config['income']['subtitle']=careers_clean((string)$_POST['income_subtitle'],500);
        $config['income']['disclaimer']=careers_clean((string)$_POST['income_disclaimer'],1200);
        for($i=0;$i<3;$i++) $config['income']['scenarios'][$i]=['label'=>careers_clean((string)($_POST['scenario_label'][$i]??''),100),'activity'=>careers_clean((string)($_POST['scenario_activity'][$i]??''),100),'income'=>careers_clean((string)($_POST['scenario_income'][$i]??''),100)];
        careers_save_config($config); $notice='Careers page content saved.'; $tab='content';
    } elseif($action==='save_job') {
        $id=careers_slug((string)($_POST['job_id']??$_POST['title']??'')); if($id==='')$id='job-'.bin2hex(random_bytes(3));
        $job=['id'=>$id,'title'=>careers_clean((string)$_POST['title'],160),'department'=>careers_clean((string)$_POST['department'],100),'location'=>careers_clean((string)$_POST['location'],120),'employment_type'=>careers_clean((string)$_POST['employment_type'],120),'status'=>in_array($_POST['status']??'', ['draft','published','closed'],true)?$_POST['status']:'draft','featured'=>!empty($_POST['featured']),'sort'=>(int)($_POST['sort']??100),'summary'=>careers_clean((string)$_POST['summary'],800),'description'=>careers_clean((string)$_POST['description'],3000),'responsibilities'=>array_values(array_filter(array_map(fn($x)=>careers_clean($x,500),preg_split('/\R/',(string)$_POST['responsibilities'])?:[]))),'requirements'=>array_values(array_filter(array_map(fn($x)=>careers_clean($x,500),preg_split('/\R/',(string)$_POST['requirements'])?:[]))),'compensation_label'=>careers_clean((string)$_POST['compensation_label'],500)];
        $found=false; foreach($config['jobs'] as $k=>$existing){ if(($existing['id']??'')===$id){$config['jobs'][$k]=$job;$found=true;break;}} if(!$found)$config['jobs'][]=$job;
        careers_save_config($config); $notice='Job saved.'; $tab='jobs';
    } elseif($action==='delete_job') {
        $id=careers_clean((string)$_POST['job_id'],100); $config['jobs']=array_values(array_filter($config['jobs'],fn($j)=>(string)($j['id']??'')!==$id)); careers_save_config($config); $notice='Job removed.'; $tab='jobs';
    } elseif($action==='update_application') {
        careers_update_application((string)$_POST['application_id'],(string)$_POST['status'],(string)$_POST['internal_notes']); $notice='Applicant updated.'; $tab='applications';
    } elseif($action==='change_password') {
        $p=(string)($_POST['new_password']??''); if(careers_admin_set_password($p))$notice='Admin password changed.'; else $error='Password must be at least 10 characters.'; $tab='settings';
    }
    $config=careers_load_config();
}
$apps=careers_all_applications();
$editJob=null; if(isset($_GET['edit']))$editJob=careers_find_job($config,careers_clean((string)$_GET['edit'],100));
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Careers Manager | EvoSys Pro</title><style>
:root{--bg:#06111d;--panel:#091a29;--line:#29445c;--text:#eef4f8;--muted:#91a6b9;--gold:#efb546}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}.top{position:sticky;top:0;background:#05101aeF;border-bottom:1px solid var(--line);padding:13px 20px;display:flex;justify-content:space-between;gap:15px;align-items:center;z-index:10}.top strong{font-size:19px}.top a{color:#dbe8f3;text-decoration:none}.layout{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 54px)}.side{border-right:1px solid var(--line);padding:18px}.side a{display:block;color:#b7c7d4;text-decoration:none;padding:11px 12px;border-radius:8px;margin-bottom:5px}.side a.active,.side a:hover{background:#0d2436;color:#fff}.main{padding:26px;max-width:1280px}.card{border:1px solid var(--line);border-radius:14px;background:var(--panel);padding:20px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.full{grid-column:1/-1}label{display:block;font-size:11px;font-weight:800;color:#c9d7e2;margin-bottom:5px}input,select,textarea{width:100%;background:#071522;border:1px solid #34546b;color:#fff;border-radius:8px;padding:10px}textarea{min-height:110px}.btn{display:inline-flex;border:0;border-radius:8px;padding:10px 13px;background:var(--gold);font-weight:850;cursor:pointer;color:#07111a;text-decoration:none}.btn.alt{background:#17344a;color:#eaf3f9}.btn.red{background:#7d2530;color:#fff}.notice{padding:12px;border:1px solid #3a725c;background:#0d2a22;border-radius:9px;margin-bottom:16px}.error{padding:12px;border:1px solid #7a3b43;background:#2b1115;border-radius:9px;margin-bottom:16px}.jobrow{display:grid;grid-template-columns:1fr auto;gap:12px;padding:14px;border:1px solid var(--line);border-radius:10px;margin-bottom:10px}.meta{color:var(--muted);font-size:12px}.pill{display:inline-block;border:1px solid #35556d;border-radius:999px;padding:3px 7px;font-size:10px;margin-left:5px}.apps{overflow:auto}.apps table{border-collapse:collapse;width:100%;min-width:900px}.apps th,.apps td{border-bottom:1px solid #203b50;padding:10px;text-align:left;font-size:12px;vertical-align:top}.apps th{color:#8fa5b9;text-transform:uppercase;letter-spacing:.06em}.small{font-size:11px;color:var(--muted)}details summary{cursor:pointer;color:#ffd77e}.scenario{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:8px}@media(max-width:820px){.layout{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line);display:flex;overflow:auto;gap:4px}.side a{white-space:nowrap}.grid,.scenario{grid-template-columns:1fr}.full{grid-column:auto}.main{padding:16px}}
</style></head><body><div class="top"><strong>EvoSys Pro — Careers Manager</strong><div><a href="../" target="_blank">View Careers Page ↗</a>&nbsp;&nbsp; <a href="?logout=1">Sign Out</a></div></div><div class="layout"><nav class="side"><?php foreach(['jobs'=>'Open Roles','content'=>'Page Content','applications'=>'Applicants','settings'=>'Settings'] as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=htmlspecialchars($v)?></a><?php endforeach;?></nav><main class="main"><?php if($notice):?><div class="notice"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?>
<?php if($tab==='jobs'):?><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><div><h1>Open Roles</h1><p class="meta">Publish, edit, close, or remove jobs without changing code.</p></div><a class="btn" href="?tab=jobs&edit=new">+ Add Role</a></div><?php foreach($config['jobs'] as $j):?><div class="jobrow"><div><strong><?=htmlspecialchars((string)$j['title'])?></strong><span class="pill"><?=htmlspecialchars((string)$j['status'])?></span><div class="meta"><?=htmlspecialchars((string)$j['department'])?> · <?=htmlspecialchars((string)$j['location'])?> · <?=htmlspecialchars((string)$j['employment_type'])?></div></div><div><a class="btn alt" href="?tab=jobs&edit=<?=rawurlencode((string)$j['id'])?>">Edit</a></div></div><?php endforeach;?><?php if(isset($_GET['edit'])):$j=$editJob?:['id'=>'','title'=>'','department'=>'Sales','location'=>'Remote (US)','employment_type'=>'Independent Contractor (1099)','status'=>'draft','featured'=>false,'sort'=>100,'summary'=>'','description'=>'','responsibilities'=>[],'requirements'=>[],'compensation_label'=>''];?><div class="card"><h2><?=$editJob?'Edit Role':'Add Role'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="save_job"><input type="hidden" name="job_id" value="<?=htmlspecialchars((string)$j['id'])?>"><div class="grid"><div><label>Job Title</label><input name="title" required value="<?=htmlspecialchars((string)$j['title'])?>"></div><div><label>Department</label><input name="department" required value="<?=htmlspecialchars((string)$j['department'])?>"></div><div><label>Location</label><input name="location" required value="<?=htmlspecialchars((string)$j['location'])?>"></div><div><label>Employment Type</label><input name="employment_type" required value="<?=htmlspecialchars((string)$j['employment_type'])?>"></div><div><label>Status</label><select name="status"><?php foreach(['draft','published','closed'] as $x):?><option <?=$j['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div><label>Sort Order</label><input type="number" name="sort" value="<?=htmlspecialchars((string)$j['sort'])?>"></div><div class="full"><label><input type="checkbox" name="featured" value="1" style="width:auto" <?=!empty($j['featured'])?'checked':''?>> Featured role</label></div><div class="full"><label>Card Summary</label><textarea name="summary"><?=htmlspecialchars((string)$j['summary'])?></textarea></div><div class="full"><label>Full Description</label><textarea name="description"><?=htmlspecialchars((string)$j['description'])?></textarea></div><div class="full"><label>Responsibilities — one per line</label><textarea name="responsibilities"><?=htmlspecialchars(implode("\n",$j['responsibilities']??[]))?></textarea></div><div class="full"><label>Requirements — one per line</label><textarea name="requirements"><?=htmlspecialchars(implode("\n",$j['requirements']??[]))?></textarea></div><div class="full"><label>Compensation Label</label><input name="compensation_label" value="<?=htmlspecialchars((string)$j['compensation_label'])?>"></div><div class="full"><button class="btn">Save Role</button></div></div></form><?php if($editJob):?><form method="post" onsubmit="return confirm('Remove this role permanently?')" style="margin-top:12px"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="delete_job"><input type="hidden" name="job_id" value="<?=htmlspecialchars((string)$j['id'])?>"><button class="btn red">Delete Role</button></form><?php endif;?></div><?php endif;?>
<?php elseif($tab==='content'):?><h1>Page Content</h1><p class="meta">Manage the public careers-page copy and projected-income examples here. No code edits.</p><form method="post" class="card"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="save_site"><div class="grid"><div><label>Hero Kicker</label><input name="hero_kicker" value="<?=htmlspecialchars((string)$config['site']['hero_kicker'])?>"></div><div><label>Hero Title</label><input name="hero_title" value="<?=htmlspecialchars((string)$config['site']['hero_title'])?>"></div><div class="full"><label>Hero Copy</label><textarea name="hero_copy"><?=htmlspecialchars((string)$config['site']['hero_copy'])?></textarea></div><div><label>Hero Visual Title</label><input name="visual_title" value="<?=htmlspecialchars((string)$config['site']['visual_title'])?>"></div><div><label>Open Roles Heading</label><input name="roles_title" value="<?=htmlspecialchars((string)$config['site']['roles_title'])?>"></div><div class="full"><label>Hero Visual Copy</label><textarea name="visual_copy"><?=htmlspecialchars((string)$config['site']['visual_copy'])?></textarea></div><div class="full"><label>Hero Visual Chips — one per line</label><textarea name="visual_chips"><?=htmlspecialchars(implode("
",$config['site']['visual_chips']??[]))?></textarea></div><div class="full"><label>Open Roles Intro</label><textarea name="roles_copy"><?=htmlspecialchars((string)$config['site']['roles_copy'])?></textarea></div><div class="full"><label>Why Work Here Heading</label><input name="why_title" value="<?=htmlspecialchars((string)$config['site']['why_title'])?>"></div><div class="full"><label>Why Work Here Cards</label><?php foreach(($config['site']['why_items']??[]) as $item):?><div class="scenario" style="grid-template-columns:1fr 2fr"><input name="why_item_title[]" value="<?=htmlspecialchars((string)$item['title'])?>"><input name="why_item_copy[]" value="<?=htmlspecialchars((string)$item['copy'])?>"></div><?php endforeach;?></div><div><label>Application Kicker</label><input name="apply_kicker" value="<?=htmlspecialchars((string)$config['site']['apply_kicker'])?>"></div><div><label>Application Heading</label><input name="apply_title" value="<?=htmlspecialchars((string)$config['site']['apply_title'])?>"></div><div class="full"><label>Application Intro</label><textarea name="apply_copy"><?=htmlspecialchars((string)$config['site']['apply_copy'])?></textarea></div><div class="full"><label><input type="checkbox" name="income_enabled" value="1" style="width:auto" <?=!empty($config['income']['enabled'])?'checked':''?>> Show projected-income section</label></div><div><label>Income Section Title</label><input name="income_title" value="<?=htmlspecialchars((string)$config['income']['title'])?>"></div><div><label>Income Section Subtitle</label><input name="income_subtitle" value="<?=htmlspecialchars((string)$config['income']['subtitle'])?>"></div><div class="full"><label>Income Scenarios</label><?php foreach($config['income']['scenarios'] as $i=>$s):?><div class="scenario"><input name="scenario_label[]" value="<?=htmlspecialchars((string)$s['label'])?>"><input name="scenario_activity[]" value="<?=htmlspecialchars((string)$s['activity'])?>"><input name="scenario_income[]" value="<?=htmlspecialchars((string)$s['income'])?>"></div><?php endforeach;?></div><div class="full"><label>Earnings Disclaimer</label><textarea name="income_disclaimer"><?=htmlspecialchars((string)$config['income']['disclaimer'])?></textarea></div><div class="full"><button class="btn">Save Page Content</button></div></div></form>
<?php elseif($tab==='applications'):?><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><h1>Applicants</h1><p class="meta"><?=count($apps)?> application(s) stored privately.</p></div><a class="btn alt" href="?tab=export">Export CSV</a></div><div class="card apps"><table><thead><tr><th>Applicant</th><th>Role</th><th>Experience</th><th>Source</th><th>Status</th><th>Submitted</th><th>Review</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><strong><?=htmlspecialchars((string)$a['full_name'])?></strong><br><?=htmlspecialchars((string)$a['email'])?><br><?=htmlspecialchars((string)$a['phone'])?><br><span class="small"><?=htmlspecialchars((string)$a['city_state'])?></span></td><td><?=htmlspecialchars((string)$a['job_title'])?><br><span class="small"><?=htmlspecialchars((string)$a['application_id'])?></span></td><td><?=htmlspecialchars((string)$a['sales_experience'])?><br><span class="small">B2B: <?=htmlspecialchars((string)$a['b2b_experience'])?> · SaaS: <?=htmlspecialchars((string)$a['saas_experience'])?></span></td><td><?=htmlspecialchars((string)$a['source'])?></td><td><?=htmlspecialchars((string)$a['status'])?></td><td><?=htmlspecialchars(substr((string)$a['submitted_at'],0,16))?></td><td><details><summary>Open</summary><form method="post" style="width:300px;margin-top:10px"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="update_application"><input type="hidden" name="application_id" value="<?=htmlspecialchars((string)$a['application_id'])?>"><p class="small"><?=htmlspecialchars((string)$a['interest'])?></p><?php if(!empty($a['linkedin'])):?><p><a style="color:#70e5de" target="_blank" href="<?=htmlspecialchars((string)$a['linkedin'])?>">LinkedIn ↗</a></p><?php endif;?><?php if(!empty($a['resume']['path'])):?><p><a style="color:#70e5de" href="?resume=<?=rawurlencode((string)$a['application_id'])?>">Download Resume</a></p><?php endif;?><label>Status</label><select name="status"><?php foreach(['New','Review','Interview','Hold','Rejected','Hired'] as $s):?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><label style="margin-top:8px">Internal Notes</label><textarea name="internal_notes"><?=htmlspecialchars((string)($a['internal_notes']??''))?></textarea><button class="btn" style="margin-top:8px">Save Applicant</button></form></details></td></tr><?php endforeach;?></tbody></table></div>
